use board::models::request;

use crate::support::{TestApp, TestResponse};

/// Submits `params` the way the form does.
async fn submit(app: &TestApp, path: &str, params: &request::RequestParams) -> TestResponse {
    let fields = [
        ("agent_id", params.agent_id.as_str()),
        ("title", params.title.as_str()),
        ("description", params.description.as_str()),
        ("category", params.category.as_str()),
        ("location", params.location.as_str()),
        ("budget", params.budget.as_str()),
    ];
    app.post_form(path, &fields).await
}
